const PROFILE_NOTICE='SC-2026-09-15-DRAFT-1';
let talentDraft={name:'',email:'',job:'',salary:'',currency:'SGD',qualification:'',start:'',language:'',dialect:'',license:'',living:'',location:'',phoneMY:'',phoneSG:'',nationality:'',dob:'',gender:'',height:'',weight:'',marital:'',religion:'',tattoo:'',history:[],terms:false,processing:false,discovery:false,status:'Draft',events:[]};
const profileFields={
  personal:[['name','姓名 / Name','text',true],['email','邮箱 / Email','email',true],['phoneMY','马来西亚手机号码 / MY mobile','tel',false],['phoneSG','新加坡手机号码 / SG mobile','tel',false]],
  work:[['job','申请的工作 / Job applied for','text',true],['salary','期望月薪 / Expected monthly salary','number',true],['currency','薪资币种 / Salary currency',['SGD','MYR'],true],['qualification','学历 / Qualification','text',true],['start','最早上班日期 / Earliest start date','date',true],['language','语言 / Languages','text',true],['dialect','方言 / Dialects','text',false],['license','新加坡3号驾照 / Singapore Class 3 licence',['Yes / 有','No / 没有'],false],['living','居住与通勤 / Living & commuting',['Stay in Singapore / 住新加坡','Commute MY–SG / 来回新马','Relocating / 计划搬迁'],true],['location','地区 / Area in Singapore or Malaysia','text',true]],
  additional:[['nationality','国籍 / Nationality','text',false],['dob','生日 / Date of birth','date',false],['gender','性别 / Gender',['Female / 女','Male / 男','Self-describe / 自行说明','Prefer not to say / 不愿透露'],false],['height','身高 / Height (cm)','number',false],['weight','体重 / Weight (kg)','number',false],['marital','婚姻状况 / Marital status',['Single / 未婚','Married / 已婚','Other / 其他','Prefer not to say / 不愿透露'],false],['religion','宗教 / Religion','text',false],['tattoo','纹身 / Tattoos',['Yes / 有','No / 没有','Prefer not to say / 不愿透露'],false]]
};
function field([key,label,type,required],value=talentDraft[key]||'',prefix=''){
 const name=prefix+key;let attr=required?' required':'';
 if(type==='number')attr+=' min="0" step="0.01"';
 if(key==='dob')attr+=` max="${new Date().toISOString().slice(0,10)}"`;
 return `<label>${label}${required?' <span class="required">*</span>':''}${Array.isArray(type)?`<select name="${name}"${attr}><option value="">请选择 / Select</option>${type.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${name}"${attr} maxlength="2000">${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}"${attr} ${type==='text'?'maxlength="200"':''}>`}</label>`;
}
function ageFromDate(dob){if(!dob)return '';const d=new Date(dob+'T00:00:00');if(Number.isNaN(d.getTime())||d>new Date())return '';const now=new Date();return now.getFullYear()-d.getFullYear()-(now.getMonth()<d.getMonth()||(now.getMonth()===d.getMonth()&&now.getDate()<d.getDate())?1:0)}
function jobFields(i){let h=talentDraft.history[i]||{};return `<fieldset class="history-entry"><legend>工作 ${i+1} / Employment ${i+1}</legend><p class="field-note">${i===0?'Most recent first. Leave all entries blank if you have no employment history. / 最近的工作优先；无工作经验可留空。':'Complete only if applicable. / 如适用请填写。'}</p><div class="form-grid">${[['company','公司名字 / Company name','text'],['position','职位 / Position','text'],['description','工作内容 / Job description','textarea'],['from','开始年月 / From','month'],['to','结束年月 / To','month'],['basic','之前底薪 / Previous basic salary','number'],['currency','币种 / Currency',['SGD','MYR']],['reason','离开原因 / Reason for leaving','textarea']].map(([k,l,t])=>field([k,l,t,false],h[k]||'',`h${i}_`)).join('')}<label class="check-row"><input type="checkbox" name="h${i}_current" ${h.current?'checked':''}>目前在职 / I currently work here</label></div></fieldset>`}
function profilePage(){return heading('YOUR PROFILE / 个人资料','Your experience. Your next chapter.','Complete your career profile, then choose who can see it. / 完善职业资料，自主选择展示范围。')+`<div class="prototype-note"><strong>Prototype / 原型演示</strong> Use sample information only. This form stays in this page’s memory and resets on refresh; it does not submit a real application or record legal consent. / 请仅使用模拟资料，刷新后清空。</div><div class="profile-layout"><form id="talent-form" onsubmit="completeProfile(event)" oninput="captureProfile(this);updateAge()" onchange="captureProfile(this);updateAge()"><section class="panel form-section" id="personal"><div class="section-title"><span>01</span><div><h2>Contact details / 联系方式</h2><p class="field-note">* Required / 必填 · Provide at least one mobile number. Contact details are excluded from discovery.</p></div></div><div class="form-grid">${profileFields.personal.map(f=>field(f)).join('')}</div></section><section class="panel form-section" id="career"><div class="section-title"><span>02</span><div><h2>Career preferences / 求职意向</h2><p class="field-note">Share the work you want and the experience you bring.</p></div></div><div class="form-grid">${profileFields.work.map(f=>field(f)).join('')}</div><p class="field-note">Area only, e.g. Woodlands or Johor Bahru. Do not enter a full residential address. / 仅填写地区，无需完整住址。</p></section><section class="panel form-section" id="employment"><div class="section-title"><span>03</span><div><h2>Employment history / 工作经历</h2><p class="field-note">Your latest three jobs, if any. Previous salary and reason for leaving are optional and private.</p></div></div>${[0,1,2].map(jobFields).join('')}</section><section class="panel form-section" id="additional"><div class="section-title"><span>04</span><div><h2>Additional details / 补充资料</h2><p class="field-note">Optional · Private · Not used for employer search or matching.</p></div></div><div class="review-note">These requested fields are included for prototype review. For general recruitment, we recommend removing non-job-related personal details before launch, in line with <a href="https://www.tal.sg/tafep/employment-practices/recruitment/preparing-job-application-forms" target="_blank" rel="noopener">TAFEP guidance</a>. Leaving them blank does not affect profile completion. / 此部分可留空，不影响资料完成。</div><div class="form-grid">${profileFields.additional.map(f=>field(f)).join('')}<label>年龄 / Age <input id="derived-age" readonly value="${ageFromDate(talentDraft.dob)}" placeholder="Calculated from DOB / 根据生日计算"></label></div></section><section class="panel form-section" id="consent"><div class="section-title"><span>05</span><div><h2>Privacy & consent / 隐私与同意</h2><p class="field-note">Draft notice ${PROFILE_NOTICE} · Mock operator: Star Collective</p></div></div>${privacySummary()}<details class="notice"><summary>Read privacy notice & profile terms / 阅读隐私声明及条款</summary>${privacyNotice()}</details><label class="check-row"><input type="checkbox" name="terms" ${talentDraft.terms?'checked':''} required><span>I have read and accept the draft profile terms below. I will provide accurate information and only share work details I am authorised to disclose. / 我已阅读并接受资料条款，确认所提供资料准确且获准披露。 <b>*</b></span></label><label class="check-row"><input type="checkbox" name="processing" ${talentDraft.processing?'checked':''} required><span>I consent to Star Collective collecting and using the information I provide to maintain my talent profile, support relevant job matching and manage introductions as described in the notice. / 我同意 Star Collective 按声明收集及使用我提供的资料，以管理个人档案、职位匹配及介绍流程。 <b>*</b></span></label><label class="check-row consent-optional"><input type="checkbox" name="discovery" ${talentDraft.discovery?'checked':''}><span><strong>Optional: make my professional profile discoverable to registered employer accounts.</strong> I consent to disclosure of only the fields listed in “Employer preview” for recruitment. My profile will not be published to the open internet. I can withdraw this choice here. / 可选：我同意向平台注册企业展示“企业预览”中列明的职业资料，仅供招聘使用，不公开至互联网；我可在此撤回。</span></label><p class="field-note">Declining employer visibility still lets you complete and keep a private profile. / 不同意企业展示，仍可完成私人档案。</p><div class="actions"><button class="btn primary" type="submit">Complete profile / 完成资料</button><button class="btn" type="button" onclick="saveTalentDraft()">Save draft / 保存草稿</button></div><p id="profile-result" class="field-note" role="status">${talentDraft.status==='Complete'?'Profile complete in this demo. / 演示资料已完成。':'Your profile is a draft. / 资料尚为草稿。'}</p></section></form><div class="profile-side"><section class="panel"><div class="eyebrow">YOU CHOOSE THE AUDIENCE</div><h2>Visibility / 展示范围</h2><span class="badge">${talentDraft.status==='Complete'&&talentDraft.discovery?'Employer discovery enabled (demo)':'Private profile (demo)'}</span><p class="sub">Your public-facing professional information is always separated from your private details.</p><button class="btn" style="width:100%;margin-top:20px" onclick="previewEmployer()">Employer preview / 企业预览</button><div class="actions"><button class="text-btn" onclick="withdrawDiscovery()">Withdraw visibility consent / 撤回展示同意</button></div></section><section class="panel"><h2>Your checklist / 资料清单</h2><a href="#personal">01 Contact details</a><a href="#career">02 Career preferences</a><a href="#employment">03 Employment history</a><a href="#additional">04 Optional details</a><a href="#consent">05 Privacy & consent</a></section><section class="panel"><h2>Consent history / 同意记录</h2><p class="field-note">Demo only; not a permanent audit record.</p>${talentDraft.events.length?talentDraft.events.slice(-4).reverse().map(e=>`<p class="event">${esc(e.action)}<small>${esc(new Date(e.at).toLocaleString())}<br>${e.version}</small></p>`).join(''):'<p class="sub">No consent recorded.</p>'}</section></div></div>`}
function privacySummary(){return `<div class="privacy-grid"><div><strong>Employer preview / 企业可见</strong><p>Name, target role, expected salary, qualification, languages/dialects, licence (if provided), start date, area, commute preference and job history excluding past pay and reasons for leaving.</p></div><div><strong>Private / 不公开</strong><p>Phone numbers, email, nationality, DOB/age, gender, height, weight, marital status, religion, tattoos, previous salary and reasons for leaving.</p></div></div>`}
function privacyNotice(){return `<div class="legal-copy"><p><strong>Draft for review—not a completed legal policy. / 待审核草案，非最终法律文件。</strong> Operator: Star Collective (mock business name; registered entity to be confirmed). DPO/privacy contact: not yet supplied. Before accepting real registrations, confirm the legal operator, publish a working DPO contact and have this notice reviewed against actual operations.</p><h3>1. Purposes / 使用目的</h3><p>The proposed service collects submitted career and contact information to maintain a talent account, help match relevant roles, manage introductions and answer profile enquiries. Optional personal details are excluded from discovery and matching; do not collect them in a live service without a documented, reasonable job-related purpose and an appropriate notice. No advertising or marketing consent is requested here.</p><h3>2. Disclosure & audience / 披露范围</h3><p>Separate employer-discovery consent covers only the professional fields listed above, disclosed to registered employer accounts for recruitment. It does not authorise public-web publication, advertising, resale or unrelated uses. In a live service, authorised operations staff and contracted service providers would access only data needed to perform their duties. Actual providers and overseas processing arrangements must be confirmed before launch. Any overseas transfer must meet applicable PDPA protection requirements.</p><p>Contact details are not included in employer discovery. Each future introduction must identify the receiving employer and the contact fields to be disclosed, and obtain the candidate’s choice before disclosure. This prototype does not disclose entered contact details to employers.</p><h3>3. Your choices / 您的选择</h3><p>Employer visibility is optional and can be withdrawn using the visibility control. Withdrawal stops future discovery in this demo. It does not recall copies already lawfully received by an employer in a live service. Requests to withdraw core processing consent, access or correct data, or close an account should be directed to the DPO; the operating contact and request process must be supplied before launch. Explain likely service consequences before processing withdrawal. Requests remain subject to applicable legal requirements and exceptions.</p><h3>4. Retention & protection / 保存与保护</h3><p>This prototype stores form entries and consent choices only in page memory, not in an account database; refreshing clears them. For production, establish purpose-based retention and deletion rules, appropriate access controls and security, consent records, and a breach-response process. Retain personal data only while required for the stated purpose or legal/business needs; cease retention or anonymise when no longer needed. Those production controls are not implemented by this prototype.</p><h3>5. Profile terms / 个人档案条款</h3><p>Provide accurate information, keep it up to date, and avoid sharing confidential employer information or another person’s data without authority. Inclusion on the platform does not guarantee an interview, job or offer. Discovery consent does not transfer ownership of your information or permit unrelated use. Material new uses require an updated notice and an appropriate lawful basis. These terms do not waive rights under applicable law.</p><p>中文摘要：资料用于档案管理、职位匹配及介绍；企业展示需另行选择同意。联系方式及补充个人资料不在企业预览中。可撤回展示同意。正式上线前，须补全注册主体、DPO联系方式、保存规则、安全控制及境外处理安排，并审核完整中英文政策。</p><p>References: <a href="https://www.pdpc.gov.sg/overview-of-pdpa/the-legislation/personal-data-protection-act/data-protection-obligations" target="_blank" rel="noopener">PDPC obligations</a> · <a href="https://www.tal.sg/tafep/employment-practices/recruitment/preparing-job-application-forms" target="_blank" rel="noopener">TAFEP application forms</a></p></div>`}
function captureProfile(form){const f=new FormData(form);for(const key of Object.keys(talentDraft)){if(['history','events','status'].includes(key))continue;talentDraft[key]=['terms','processing','discovery'].includes(key)?f.has(key):String(f.get(key)||'').trim()}
talentDraft.history=[0,1,2].map(i=>Object.fromEntries(['company','position','description','from','to','basic','currency','reason','current'].map(k=>[k,k==='current'?f.has(`h${i}_${k}`):String(f.get(`h${i}_${k}`)||'').trim()])));
talentDraft.status='Draft';}
function updateAge(){const el=document.querySelector('#derived-age');if(el)el.value=ageFromDate(talentDraft.dob)}
function profileErrors(d){const errors=[];for(const f of [...profileFields.personal,...profileFields.work])if(f[3]&&!String(d[f[0]]||'').trim())errors.push(f[1]+' is required.');if(!d.phoneMY&&!d.phoneSG)errors.push('Provide at least one MY or SG mobile number. / 请填写至少一个手机号码。');for(const phone of [d.phoneMY,d.phoneSG])if(phone&&!/^\+?[\d\s()-]{7,20}$/.test(phone))errors.push('Enter a valid mobile number.');if(d.salary!==''&&(!Number.isFinite(Number(d.salary))||Number(d.salary)<0))errors.push('Expected salary must be a valid non-negative number.');if(d.dob&&ageFromDate(d.dob)==='')errors.push('Date of birth must be a valid date in the past.');d.history.forEach((h,i)=>{const used=Object.entries(h).some(([k,v])=>k!=='currency'&&v);if(!used)return;if(!h.company||!h.position||!h.description||!h.from||(!h.current&&!h.to))errors.push(`Employment ${i+1}: provide company, position, description and working period.`);if(h.current&&h.to)errors.push(`Employment ${i+1}: clear the end date for a current job.`);if(h.to&&h.from>h.to)errors.push(`Employment ${i+1}: end month must follow start month.`);const month=new Date().toISOString().slice(0,7);if(h.from>month||h.to>month)errors.push(`Employment ${i+1}: working dates cannot be in the future.`);if(h.basic&&!h.currency)errors.push(`Employment ${i+1}: select a currency for previous salary.`)});if(!d.terms||!d.processing)errors.push('Read and select both required agreements to complete your profile.');return errors}
function consentEvent(action){talentDraft.events.push({action,at:new Date().toISOString(),version:PROFILE_NOTICE,processing:talentDraft.processing,terms:talentDraft.terms,discovery:talentDraft.discovery})}
function completeProfile(e){e.preventDefault();captureProfile(e.target);const errors=profileErrors(talentDraft);if(errors.length){const out=document.querySelector('#profile-result');out.textContent=errors.join(' ');out.classList.add('form-error');out.scrollIntoView({block:'center'});return}talentDraft.status='Complete';consentEvent(talentDraft.discovery?'Completed with employer visibility':'Completed as a private profile');state.profile.name=talentDraft.name;state.profile.role=talentDraft.job;render();toast('Demo profile completed. '+(talentDraft.discovery?'Employer visibility selected.':'Kept private.'))}
function saveTalentDraft(){captureProfile(document.querySelector('#talent-form'));render();toast('Draft saved in this page only. Refreshing clears it.')}
function withdrawDiscovery(){const f=document.querySelector('#talent-form');if(f)captureProfile(f);talentDraft.discovery=false;consentEvent('Employer visibility consent withdrawn');render();toast('Employer visibility consent withdrawn in this demo.')}
function employerData(d){return {name:d.name,job:d.job,salary:d.salary,currency:d.currency,qualification:d.qualification,language:d.language,dialect:d.dialect,license:d.license,start:d.start,living:d.living,location:d.location,history:d.history.filter(h=>h.company).map(({company,position,description,from,to,current})=>({company,position,description,from,to,current}))}}
function previewEmployer(){const f=document.querySelector('#talent-form');if(f)captureProfile(f);const p=employerData(talentDraft);modal(`<div class="eyebrow">EMPLOYER PREVIEW / 企业预览</div><h2>${esc(p.name||'Your name')}</h2><p class="sub">${esc(p.job||'Your target role')}</p><div class="callout">Preview only. ${talentDraft.discovery?'You have selected employer visibility; complete the form to record the demo choice.':'Your visibility consent is off. Employers would not see this profile.'}</div><dl class="preview-list">${Object.entries({Qualification:p.qualification,'Expected monthly salary':p.salary?`${p.currency} ${p.salary}`:'',Languages:p.language,Dialects:p.dialect,'Class 3 licence':p.license,'Earliest start':p.start,Area:p.location,'Living & commuting':p.living}).map(([k,v])=>`<dt>${k}</dt><dd>${esc(v||'Not supplied')}</dd>`).join('')}</dl>${p.history.map(h=>`<div class="fit"><strong>${esc(h.position)} · ${esc(h.company)}</strong>${esc(h.from)} – ${h.current?'Present':esc(h.to)}<p>${esc(h.description)}</p></div>`).join('')}<p class="field-note">Contact details, additional personal information, past salary and reasons for leaving are excluded.</p>`)}
